132:     this.eventListeners.get(method).push(handler);
133:   }
134: 
135:   async evaluate(expression, awaitPromise = true) {
136:     const res = await this.send('Runtime.evaluate', {
137:       expression,
138:       awaitPromise,
139:       returnByValue: true
140:     });
141:     if (res.exceptionDetails) {
142:       throw new Error(
143:         res.exceptionDetails.exception
144:           ? (res.exceptionDetails.exception.description || res.exceptionDetails.exception.value)
145:           : 'Evaluation exception'
146:       );
147:     }
148:     return res.result ? res.result.value : undefined;
149:   }
150: 
151:   close() {
152:     if (this.ws) {
153:       try { this.ws.close(); } catch (_) {}
154:       this.ws = null;
155:     }
156:   }
157: }
