178: // Helper to wait for seek completion
179: async function waitForSeekCompletion(cdpClient, timeoutMs = 12000) {
180:   const t0 = Date.now();
181:   while (Date.now() - t0 < timeoutMs) {
182:     const status = await cdpClient.evaluate(`(() => {
183:       const v = document.getElementById("main-video-player");
184:       return {
185:         currentTime: v.currentTime,
186:         paused: v.paused,
187:         seeking: v.seeking,
188:         readyState: v.readyState,
189:         bufferedEnd: v.buffered.length > 0 ? v.buffered.end(v.buffered.length - 1) : 0
190:       };
191:     })()`);
192:     if (!status.seeking && status.readyState >= 3) {
193:       return status;
194:     }
195:     await sleep(400);
196:   }
197:   return await cdpClient.evaluate(`(() => {
198:     const v = document.getElementById("main-video-player");
199:     return {
200:       currentTime: v.currentTime,
201:       paused: v.paused,
202:       seeking: v.seeking,
203:       readyState: v.readyState,
204:       bufferedEnd: v.buffered.length > 0 ? v.buffered.end(v.buffered.length - 1) : 0
205:     };
206:   })()`);
207: }
