79: function installScrollMocks(window) {
80:   window.Element.prototype.scrollIntoView = function (options) {
81:     this._lastScrollIntoView = options || true;
82:   };
83: 
84:   window.Element.prototype.scrollTo = function (x, y) {
85:     if (typeof x === 'object') {
86:       this.scrollLeft = x.left !== undefined ? x.left : (this.scrollLeft || 0);
87:       this.scrollTop = x.top !== undefined ? x.top : (this.scrollTop || 0);
88:       this._lastScrollBehavior = x.behavior || 'auto';
89:     } else {
90:       this.scrollLeft = x !== undefined ? x : (this.scrollLeft || 0);
91:       this.scrollTop = y !== undefined ? y : (this.scrollTop || 0);
92:     }
93:   };
94: }
95: 
96: function setupLayoutMock(window) {
97:   function makeRect(left, top, width, height) {
98:     return {
99:       left: left,
100:       top: top,
101:       width: width,
102:       height: height,
103:       right: left + width,
104:       bottom: top + height,
105:       x: left,
106:       y: top
107:     };
108:   }
109: 
110:   window.Element.prototype.getBoundingClientRect = function () {
111:     // 1. Dynamic override via data-mock-rect attribute
112:     var mockAttr = this.getAttribute('data-mock-rect');
113:     if (mockAttr) {
114:       try {
115:         var parsed = JSON.parse(mockAttr);
116:         return makeRect(parsed.left || 0, parsed.top || 0, parsed.width || 0, parsed.height || 0);
117:       } catch (err) {}
118:     }
119: 
120:     // 2. Elements with display: none or inside non-active views have zero geometry
121:     var view = this.closest('.view');
122:     if (view && !view.classList.contains('active')) {
123:       return makeRect(0, 0, 0, 0);
124:     }
125:     if (this.style.display === 'none') {
126:       return makeRect(0, 0, 0, 0);
127:     }
128: 
129:     // 3. Known component mappings
130:     var id = this.id;
131:     if (id === 'hero-play-btn') return makeRect(96, 460, 180, 56);
132:     if (id === 'hero-details-btn') return makeRect(292, 460, 140, 56);
133:     if (id === 'hero-list-btn') return makeRect(433, 460, 140, 56);
134:     if (id === 'details-play-btn') return makeRect(96, 450, 180, 56);
135:     if (id === 'details-trailer-btn') return makeRect(292, 450, 160, 56);
136:     if (id === 'player-back-btn') return makeRect(96, 54, 56, 56);
137:     if (id === 'osd-play-btn') return makeRect(912, 940, 96, 96);
138:     if (id === 'osd-rewind-btn') return makeRect(840, 940, 56, 56);
139:     if (id === 'osd-forward-btn') return makeRect(1024, 940, 56, 56);
140: 
141:     // Header brand & nav items
142:     if (this.classList.contains('brand-container')) return makeRect(96, 24, 200, 48);
143:     if (this.classList.contains('nav-pill-item')) {
144:       var route = this.getAttribute('data-route');
145:       if (route === 'home') return makeRect(790, 28, 75, 40);
146:       if (route === 'movies') return makeRect(875, 28, 85, 40);
147:       if (route === 'series') return makeRect(970, 28, 80, 40);
148:       if (route === 'search') return makeRect(1060, 28, 80, 40);
149:     }
150: 
151:     // Content Shelves
152:     if (this.classList.contains('content-shelf')) {
153:       var shelfIdx = Array.from(this.parentElement.children).indexOf(this);
154:       return makeRect(0, 560 + shelfIdx * 400, 1920, 380);
155:     }
156: 
157:     // Poster cards
158:     if (this.classList.contains('card-poster')) {
159:       var parent = this.parentElement;
160:       var index = Array.from(parent.children).indexOf(this);
161:       var grid = this.closest('.content-grid-6col');
162:       if (grid) {
163:         var col = index % 6;
164:         var row = Math.floor(index / 6);
165:         return makeRect(96 + col * 288, 180 + row * 424, 264, 396);
166:       }
167:       var isShelf1 = parent.closest('.content-shelf:nth-of-type(2)') || parent.closest('#shelf-trending');
168:       var top = isShelf1 ? 680 : 1060;
169:       return makeRect(96 + index * 244, top, 220, 330);
170:     }
171: 
172:     // Provider cards
173:     if (this.classList.contains('card-provider')) {
174:       var pIndex = Array.from(this.parentElement.children).indexOf(this);
175:       return makeRect(96 + pIndex * 184, 560, 160, 80);
176:     }
177: 
178:     // Episode cards
179:     if (this.classList.contains('card-episode')) {
180:       var epIndex = Array.from(this.parentElement.children).indexOf(this);
181:       return makeRect(96 + epIndex * 344, 670, 320, 180);
182:     }
183: 
184:     // Filter pills
185:     if (this.classList.contains('filter-pill')) {
186:       var fIndex = Array.from(this.parentElement.children).indexOf(this);
187:       return makeRect(96 + fIndex * 130, 110, 110, 44);
188:     }
189: 
190:     // Virtual keyboard keys
191:     if (this.classList.contains('key-btn')) {
192:       var rowEl = this.closest('.keyboard-row');
193:       var rIdx = rowEl ? Array.from(rowEl.parentElement.children).indexOf(rowEl) : 0;
194:       var cIdx = rowEl ? Array.from(rowEl.children).indexOf(this) : 0;
195:       return makeRect(96 + cIdx * 60, 220 + rIdx * 60, 50, 50);
196:     }
197: 
198:     // Default fallback
199:     return makeRect(96, 100, 100, 40);
200:   };
201: }
