237: function sendKey(window, key, keyCode) {
238:   const event = new window.KeyboardEvent('keydown', {
239:     key: key,
240:     keyCode: keyCode,
241:     which: keyCode,
242:     bubbles: true,
243:     cancelable: true
244:   });
245:   window.dispatchEvent(event);
246:   return event;
247: }
248: 
249: function stepKey(window, key, keyCode) {
250:   if (window.SpatialNav && typeof window.SpatialNav.resetThrottle === 'function') {
251:     window.SpatialNav.resetThrottle();
252:   }
253:   return sendKey(window, key, keyCode);
254: }
