89: // 3. Layout and Scroll Mock Infrastructure
90: function installScrollMocks(window) {
91:   window.Element.prototype.scrollIntoView = function (options) {
92:     this._lastScrollIntoView = options || true;
93:   };
94: 
95:   window.Element.prototype.scrollTo = function (x, y) {
96:     if (typeof x === 'object') {
97:       this.scrollLeft = x.left !== undefined ? x.left : (this.scrollLeft || 0);
98:       this.scrollTop = x.top !== undefined ? x.top : (this.scrollTop || 0);
99:       this._lastScrollBehavior = x.behavior || 'auto';
100:     } else {
101:       this.scrollLeft = x !== undefined ? x : (this.scrollLeft || 0);
102:       this.scrollTop = y !== undefined ? y : (this.scrollTop || 0);
103:     }
104:   };
105: }
106: 
107: function setupLayoutMock(window) {
108:   function makeRect(left, top, width, height) {
109:     return {
110:       left: left,
111:       top: top,
112:       width: width,
113:       height: height,
114:       right: left + width,
115:       bottom: top + height,
116:       x: left,
117:       y: top
118:     };
119:   }
120: 
121:   window.Element.prototype.getBoundingClientRect = function () {
122:     // 1. Dynamic override via data-mock-rect attribute
123:     var mockAttr = this.getAttribute('data-mock-rect');
124:     if (mockAttr) {
125:       try {
126:         var parsed = JSON.parse(mockAttr);
127:         return makeRect(parsed.left || 0, parsed.top || 0, parsed.width || 0, parsed.height || 0);
128:       } catch (err) {}
129:     }
130: 
131:     // 2. Elements with display: none or inside non-active views have zero geometry
132:     var view = this.closest('.view');
133:     if (view && !view.classList.contains('active')) {
134:       return makeRect(0, 0, 0, 0);
135:     }
136:     if (this.style.display === 'none') {
137:       return makeRect(0, 0, 0, 0);
138:     }
139: 
140:     // 3. Known component mappings
141:     var id = this.id;
142:     if (id === 'hero-play-btn') return makeRect(96, 460, 180, 56);
143:     if (id === 'hero-details-btn') return makeRect(292, 460, 140, 56);
144:     if (id === 'hero-list-btn') return makeRect(433, 460, 140, 56);
145:     if (id === 'details-play-btn') return makeRect(96, 450, 180, 56);
146:     if (id === 'details-trailer-btn') return makeRect(292, 450, 160, 56);
147:     if (id === 'player-back-btn') return makeRect(96, 54, 56, 56);
148:     if (id === 'osd-play-btn') return makeRect(912, 940, 96, 96);
149:     if (id === 'osd-rewind-btn') return makeRect(840, 940, 56, 56);
150:     if (id === 'osd-forward-btn') return makeRect(1024, 940, 56, 56);
151: 
152:     // Header brand & nav items
153:     if (this.classList.contains('brand-container')) return makeRect(96, 24, 200, 48);
154:     if (this.classList.contains('nav-pill-item')) {
155:       var route = this.getAttribute('data-route');
156:       if (route === 'home') return makeRect(790, 28, 75, 40);
157:       if (route === 'movies') return makeRect(875, 28, 85, 40);
158:       if (route === 'series') return makeRect(970, 28, 80, 40);
159:       if (route === 'search') return makeRect(1060, 28, 80, 40);
160:     }
161: 
162:     // Content Shelves
163:     if (this.classList.contains('content-shelf')) {
164:       var parentShelves = this.parentElement ? Array.from(this.parentElement.children) : [];
165:       var shelfIdx = parentShelves.indexOf(this);
166:       return makeRect(0, 560 + Math.max(0, shelfIdx) * 400, 1920, 380);
167:     }
168: 
169:     // Poster cards
170:     if (this.classList.contains('card-poster')) {
171:       var parent = this.parentElement;
172:       var index = parent ? Array.from(parent.children).indexOf(this) : 0;
173:       var grid = this.closest('.content-grid-6col');
174:       if (grid) {
175:         var col = index % 6;
176:         var row = Math.floor(index / 6);
177:         return makeRect(96 + col * 288, 180 + row * 424, 264, 396);
178:       }
179:       var isShelf1 = parent && (parent.closest('.content-shelf:nth-of-type(2)') || parent.closest('#shelf-trending'));
180:       var top = isShelf1 ? 680 : 1060;
181:       return makeRect(96 + index * 244, top, 220, 330);
182:     }
183: 
184:     // Provider cards
185:     if (this.classList.contains('card-provider')) {
186:       var pIndex = this.parentElement ? Array.from(this.parentElement.children).indexOf(this) : 0;
187:       return makeRect(96 + pIndex * 184, 560, 160, 80);
188:     }
189: 
190:     // Episode cards
191:     if (this.classList.contains('card-episode')) {
192:       var epIndex = this.parentElement ? Array.from(this.parentElement.children).indexOf(this) : 0;
193:       return makeRect(96 + epIndex * 344, 670, 320, 180);
194:     }
195: 
196:     // Filter pills
197:     if (this.classList.contains('filter-pill')) {
198:       var fIndex = this.parentElement ? Array.from(this.parentElement.children).indexOf(this) : 0;
199:       return makeRect(96 + fIndex * 130, 110, 110, 44);
200:     }
201: 
202:     // Virtual keyboard keys: row layout
203:     if (this.classList.contains('key-btn')) {
204:       var rowEl = this.closest('.keyboard-row');
205:       var rIdx = rowEl && rowEl.parentElement ? Array.from(rowEl.parentElement.children).indexOf(rowEl) : 0;
206:       var cIdx = rowEl ? Array.from(rowEl.children).indexOf(this) : 0;
207:       
208:       // Special width for space/backspace/clear
209:       var w = 50;
210:       var h = 50;
211:       if (this.classList.contains('key-space')) {
212:         w = 320;
213:       } else if (this.classList.contains('key-wide')) {
214:         w = 140;
215:       }
216:       var xOffset = 96 + cIdx * 60;
217:       if (rIdx === 4) { // Row 5 actions
218:         if (cIdx === 1) xOffset = 96 + 330;
219:         if (cIdx === 2) xOffset = 96 + 330 + 150;
220:       }
221:       return makeRect(xOffset, 220 + rIdx * 60, w, h);
222:     }
223: 
224:     // Default fallback
225:     return makeRect(96, 100, 100, 40);
226:   };
227: }
