512: function installMockFetch(window, customRoutes) {
513:   var routes = Object.assign({}, DEFAULT_MOCK_ROUTES, customRoutes || {});
514:   window._fetchCalls = [];
515: 
516:   var sortedPatterns = Object.keys(routes).sort(function (a, b) {
517:     return b.length - a.length;
518:   });
519: 
520:   window.fetch = function (url, options) {
521:     var urlStr = String(url);
522:     window._fetchCalls.push({ url: urlStr, options: options || {} });
523: 
524:     for (var i = 0; i < sortedPatterns.length; i++) {
525:       var pattern = sortedPatterns[i];
526:       var isMatch = pattern.startsWith('^')
527:         ? new RegExp(pattern).test(urlStr)
528:         : urlStr.indexOf(pattern) !== -1;
529: 
530:       if (isMatch) {
531:           var handler = routes[pattern];
532:           var responseData = typeof handler === 'function' ? handler(urlStr, options) : handler;
533: 
534:           if (responseData && responseData._errorStatus) {
535:             return Promise.resolve({
536:               ok: false,
537:               status: responseData._errorStatus,
538:               statusText: responseData._errorText || 'Error',
539:               json: function () { return Promise.reject(new Error(responseData._errorText || 'HTTP Error')); },
540:               text: function () { return Promise.resolve(responseData._errorText || 'HTTP Error'); }
541:             });
542:           }
543: 
544:           return Promise.resolve({
545:             ok: true,
546:             status: 200,
547:             statusText: 'OK',
548:             json: function () { return Promise.resolve(JSON.parse(JSON.stringify(responseData))); },
549:             text: function () { return Promise.resolve(JSON.stringify(responseData)); }
550:           });
551:         }
552:     }
553: 
554:     // Default 404
555:     return Promise.resolve({
556:       ok: false,
557:       status: 404,
558:       statusText: 'Not Found',
559:       json: function () { return Promise.resolve({ error: true, message: 'Not found: ' + urlStr }); },
560:       text: function () { return Promise.resolve('{"error":"Not found"}'); }
561:     });
562:   };
563: }
