553: function createM5Harness(options) {
554:   const opts = options || {};
555: 
556:   const htmlPath = path.resolve(__dirname, 'index.html');
557:   const configPath = path.resolve(__dirname, 'js/config.js');
558:   const navPath = path.resolve(__dirname, 'js/navigation.js');
559:   const tmdbPath = path.resolve(__dirname, 'js/tmdb.js');
560:   const homePath = path.resolve(__dirname, 'js/views/home.js');
561:   const catalogPath = path.resolve(__dirname, 'js/views/catalog.js');
562:   const searchPath = path.resolve(__dirname, 'js/views/search.js');
563:   const detailsPath = path.resolve(__dirname, 'js/views/details.js');
564:   const playerPath = path.resolve(__dirname, 'js/player.js');
565:   const appPath = path.resolve(__dirname, 'js/app.js');
566: 
567:   const html = fs.readFileSync(htmlPath, 'utf8');
568:   const dom = new JSDOM(html, {
569:     url: 'http://localhost/#home',
570:     runScripts: 'outside-only'
571:   });
572:   const window = dom.window;
573: 
574:   window.__TEST_M5__ = true;
575: 
576:   // Virtualized Clock Engine
577:   let virtualTime = 0;
578:   let timerSeq = 1;
579:   const virtualTimers = new Map();
580: 
581:   const origSetTimeout = window.setTimeout.bind(window);
582:   const origClearTimeout = window.clearTimeout.bind(window);
583:   const origSetInterval = window.setInterval.bind(window);
584:   const origClearInterval = window.clearInterval.bind(window);
585: 
586:   window.advanceClock = function (ms) {
587:     virtualTime += ms;
588:     let firedAny = true;
589:     while (firedAny) {
590:       firedAny = false;
591:       const readyTimers = [];
592:       virtualTimers.forEach((timer, id) => {
593:         if (timer.fireAt <= virtualTime) {
594:           readyTimers.push({ id, ...timer });
595:         }
596:       });
597:       readyTimers.sort((a, b) => a.fireAt - b.fireAt);
598:       for (const t of readyTimers) {
599:         if (!virtualTimers.has(t.id)) continue;
600:         firedAny = true;
601:         if (t.interval) {
602:           t.fireAt += t.interval;
603:           virtualTimers.set(t.id, t);
604:         } else {
605:           virtualTimers.delete(t.id);
606:         }
607:         try {
608:           t.callback();
609:         } catch (err) {
610:           console.error('[VirtualTimer Error]', err);
611:         }
612:       }
613:     }
614:   };
615: 
616:   window.setTimeout = function (callback, delay) {
617:     const d = Number(delay) || 0;
618:     if (d >= 200) {
619:       const id = timerSeq++;
620:       virtualTimers.set(id, { callback, fireAt: virtualTime + d, interval: null });
621:       return id;
622:     }
623:     return origSetTimeout(callback, delay);
624:   };
625: 
626:   window.clearTimeout = function (id) {
627:     if (virtualTimers.has(id)) {
628:       virtualTimers.delete(id);
629:       return;
630:     }
631:     return origClearTimeout(id);
632:   };
633: 
634:   window.setInterval = function (callback, delay) {
635:     const d = Number(delay) || 0;
636:     if (d >= 200) {
637:       const id = timerSeq++;
638:       virtualTimers.set(id, { callback, fireAt: virtualTime + d, interval: d });
639:       return id;
640:     }
641:     return origSetInterval(callback, delay);
642:   };
643: 
644:   window.clearInterval = function (id) {
645:     if (virtualTimers.has(id)) {
646:       virtualTimers.delete(id);
647:       return;
648:     }
649:     return origClearInterval(id);
650:   };
651: 
652:   installLayoutMock(window);
653:   installVideoMock(window);
654:   installHlsMock(window);
655:   installMockFetch(window, opts.onFetch);
656: 
657:   // Load scripts in deterministic order
